import cv2, os, timeimport numpy as npfrom picamera2 import Picamera2from flask import Flask, Response, request, jsonify, render_template_string# ======== 配置 ========CLASSES = [    "Star","Octagon","Cross","Trapezium","Diamond","CuttedCircle",    "QuarterCircle","ArrowUp","ArrowDown","ArrowLeft","ArrowRight",    "RecycleSign","ButtonSign","WarningSign"]SAVE_DIR = "dataset"# ======== 初始化摄像头 ========picam2 = Picamera2()picam2.configure(picam2.create_video_configuration(    main={"size": (640,480), "format": "BGR888"}))picam2.start()# ======== Flask 应用 ========app = Flask(__name__)# ======== MJPEG 视频流 ========def gen_frames():    while True:        frame = picam2.capture_array()        ret, buffer = cv2.imencode('.jpg', frame)        frame = buffer.tobytes()        yield (b'--frame\r\n'            b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n')@app.route("/stream")def stream():    return Response(gen_frames(),                    mimetype='multipart/x-mixed-replace; boundary=frame')# ======== 网页 UI（内嵌 HTML 模板） ========PAGE_HTML = """<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Dataset Collector</title><style>body { font-family: Arial; background: #111; color: white; text-align: center; }button { padding: 10px 20px; margin: 5px; font-size: 18px; }select { font-size: 18px; padding: 5px; }#log { margin-top: 15px; color: #0f0; }</style></head><body><h2>📷 Raspberry Pi Dataset Collector</h2><img src="/stream" width="640" /><br><br><select id="cls">  {% for c in classes %}  <option value="{{c}}">{{c}}</option>  {% endfor %}</select><br><br><button onclick="capture()">拍照</button><p id="log"></p><script>function capture(){    let cls = document.getElementById("cls").value;    let form = new FormData();    form.append("cls", cls);    fetch("/capture", { method:"POST", body:form })      .then(r => r.json())      .then(j => {          document.getElementById("log").innerText = "已保存：" + j.saved;      });}</script></body></html>"""@app.route("/")def index():    return render_template_string(PAGE_HTML, classes=CLASSES)# ======== 拍照接口 ========@app.route("/capture", methods=["POST"])def capture():    cls = request.form["cls"]    folder = os.path.join(SAVE_DIR, cls)    os.makedirs(folder, exist_ok=True)    frame = picam2.capture_array()    ts = int(time.time() * 1000)    path = os.path.join(folder, f"{cls}_{ts}.jpg")    cv2.imwrite(path, frame)    return jsonify({"saved": path})# ======== 启动 ========if __name__ == "__main__":    print("网页采集器启动成功！")    print("访问：http://<树莓派IP>:5000")    app.run(host="0.0.0.0", port=5000, debug=False, threaded=True)